arguments.query:
CREATE TABLE IF NOT EXISTS todos (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, status TEXT DEFAULT 'pending', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS todo_deps (todo_id TEXT, depends_on TEXT, PRIMARY KEY (todo_id, depends_on));
INSERT OR REPLACE INTO todos (id, title, description, status, updated_at) VALUES ('build-quiz-page', 'Build quiz page', 'Create index.html containing a standalone React-style computer languages quiz with three checkbox-group questions, modern styling, first-question help text, form-field wrappers, and submit button.', 'in_progress', CURRENT_TIMESTAMP);

