+  <body>
+    <a class="skip-link" href="#main">Skip to main content</a>
+    <div class="page-shell">
+      <header>
+        <p class="eyebrow">Multiple-answer quiz</p>
+        <h1>Computer Languages Quiz</h1>
+        <p class="intro">Select every answer that applies for each question, then submit your choices.</p>
+      </header>
+      <main id="main">
+        <div id="quiz-root"></div>
+      </main>
+    </div>
+
+    <script>
+      const quizQuestions = [
+        {
+          id: "compiled-languages",
+          prompt: "Which of these are commonly compiled programming languages?",
+          helpText: "Choose all languages that are typically compiled before running, even if some can also be interpreted or used with just-in-time compilers.",
+          choices: ["C", "JavaScript", "Rust", "Go"]
+        },
+        {
+          id: "web-languages",
+          prompt: "Which languages are commonly used to build web applications?",
+          choices: ["JavaScript", "Python", "HTML", "SQL"]
+        },
+        {
+          id: "systems-languages",
+          prompt: "Which languages are often used for systems programming?",
+          choices: ["C++", "Rust", "Swift", "Assembly"]
+        }
+      ];
+
+      function Choice({ questionId, index, label }) {
+        const choiceId = `${questionId}-${index}`;
+
+        return `
+          <label class="choice" for="${choiceId}">
+            <input id="${choiceId}" name="${questionId}" type="checkbox" value="${label}">
+            <span class="choice-text">${label}</span>
+          </label>
+        `;
+      }
+
+      function QuizQuestion({ question, number }) {
+        const helpId = `${question.id}-help`;
+        const describedBy = question.helpText ? ` aria-describedby="${helpId}"` : "";
+        const helpText = question.helpText
+          ? `<p class="help-text" id="${helpId}">${question.helpText}</p>`
+          : "";
+        const choices = question.choices
+          .map((choice, index) => Choice({ questionId: question.id, index, label: choice }))
+          .join("");
+
+        return `
+          <div class="form-field">
+            <fieldset${describedBy}>
+              <legend>${number}. ${question.prompt}</legend>
+              ${helpText}
+              <div class="choice-grid">
+                ${choices}
+              </div>
+            </fieldset>
+          </div>
+        `;
+      }
+
+      function QuizApp({ questions }) {
+        const fields = questions
+          .map((question, index) => QuizQuestion({ question, number: index + 1 }))
+          .join("");
+
+        return `
+          <form class="quiz-card" id="language-quiz">
+            <div class="quiz-content">
+              ${fields}
+            </div>
+            <div class="actions">
+              <button type="submit">Submit answers</button>
+              <p class="result" id="quiz-result" aria-live="polite"></p>
+            </div>
+          </form>
+        `;
+      }
+
+      const quizRoot = document.querySelector("#quiz-root");
+      quizRoot.innerHTML = QuizApp({ questions: quizQuestions });
+
+      document.querySelector("#language-quiz").addEventListener("submit", (event) => {
+        event.preventDefault();
+
+        const selectedCount = document.querySelectorAll("#language-quiz input:checked").length;
+        const result = document.querySelector("#quiz-result");
+        result.textContent = selectedCount === 1
+          ? "You selected 1 answer."
+          : `You selected ${selectedCount} answers.`;
+      });
+    </script>
+  </body>
